"use client";

// 必要な外部モジュールをインポート
import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  ReactNode,
  useCallback,
  useMemo,
} from "react";
import {
  User,
  onAuthStateChanged,
  signInWithEmailAndPassword,
  signOut,
  Auth,
} from "firebase/auth";
// 必要な内部モジュールをインポート
import { getAuthInstance } from "@/lib/firebase"; // 認証インスタンスを取得する関数をインポート
import { useRouter } from "next/navigation";

// =======================================================
// 1. Contextの定義と型
// =======================================================

/**
 * 認証コンテキストが持つべきデータと関数の型定義
 */
export interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  isLoggingOut: boolean;
  login: (credentials: { email: string; password: string }) => Promise<void>;
  logout: (redirectPath?: string) => Promise<void>;
  token: string | null;
}

// Contextを作成。初期値は null で、使用時に型ガード (nullチェック) を行う
const AuthContext = createContext<AuthContextType | null>(null);

// =======================================================
// 2. Auth Provider (状態管理コンポーネント)
// =======================================================

export function AuthProvider({ children }: { children: ReactNode }) {
  const router = useRouter();
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(null);
  // 初期ロードは、Firebaseインスタンスの取得と状態変更の解決を待つ
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isLoggingOut, setIsLoggingOut] = useState<boolean>(false);

  const isAuthenticated = useMemo(() => !!user, [user]);

  // 認証状態のリスナーと初期化
  useEffect(() => {
    // ライフサイクル内で Firebase Auth インスタンスを取得
    const firebaseAuth = getAuthInstance();

    if (!firebaseAuth) {
      // インスタンスが取得できなかった場合（設定不足など）
      console.error(
        "Firebase Auth service is not initialized or failed to initialize."
      );
      setIsLoading(false);
      return;
    }

    // Authインスタンスが存在する場合のみリスナーを設定
    const unsubscribe = onAuthStateChanged(
      firebaseAuth,
      async (currentUser) => {
        setUser(currentUser);

        if (currentUser) {
          try {
            // トークンを取得し、認証情報を更新
            const idToken = await currentUser.getIdToken();
            setToken(idToken);
            console.log(
              "✅ Firebase Auth State Changed: User logged in. Token stored."
            );
          } catch (e) {
            console.error("Failed to get Firebase ID Token:", e);
            setToken(null);
          }
        } else {
          setToken(null);
          console.log("✅ Firebase Auth State Changed: User logged out.");
        }
        setIsLoading(false); // 認証状態の解決が完了
      }
    );

    return () => unsubscribe();
  }, []);

  // ログイン処理
  const login = useCallback(
    async ({
      email,
      password,
    }: {
      email: string;
      password: string;
    }): Promise<void> => {
      setIsLoading(true);
      try {
        const firebaseAuth = getAuthInstance(); // 実行時にインスタンスを取得
        if (!firebaseAuth) throw new Error("Auth service is unavailable.");
        await signInWithEmailAndPassword(firebaseAuth, email, password);
      } catch (error: any) {
        console.error("Login Error:", error.code, error.message);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    []
  );

  // ログアウト処理
  const logout = useCallback(
    async (redirectPath: string = "/"): Promise<void> => {
      setIsLoggingOut(true);
      try {
        const firebaseAuth = getAuthInstance(); // 実行時にインスタンスを取得
        if (!firebaseAuth) return;
        await signOut(firebaseAuth);
        router.push(redirectPath);
      } catch (error) {
        console.error("Logout Error:", error);
      } finally {
        setIsLoggingOut(false);
      }
    },
    [router]
  );

  // コンテキストの値をメモ化
  const contextValue: AuthContextType = useMemo(
    () => ({
      user,
      isAuthenticated,
      isLoading,
      isLoggingOut,
      login,
      logout,
      token,
    }),
    [user, isAuthenticated, isLoading, isLoggingOut, token, login, logout]
  );

  // 認証状態の解決が完了するまで表示するローディングコンポーネントを定義
  const LoadingScreen = (
    <div className="min-h-screen flex items-center justify-center bg-gray-900 text-white">
      <div className="animate-spin rounded-full h-10 w-10 border-4 border-t-4 border-red-500 border-opacity-25 border-t-red-500"></div>
      <p className="ml-4">認証状態を確認中...</p>
    </div>
  );

  // 認証状態の解決が完了するまで、ローディング画面を表示
  return (
    <AuthContext.Provider value={contextValue}>
      {isLoading ? LoadingScreen : children}
    </AuthContext.Provider>
  );
}

// =======================================================
// 3. Custom Hook (useAuth)
// =======================================================

/**
 * 認証コンテキストの値にアクセスするためのカスタムフック
 * @returns AuthContextType
 * @throws Error if used outside of an AuthProvider
 */
export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);

  if (context === null) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  // nullチェック後に AuthContextType であることを保証
  return context;
};
