// @/lib/firebase.ts
import { initializeApp, FirebaseApp } from "firebase/app";
import { getAuth, Auth } from "firebase/auth";

let appInstance: FirebaseApp | null = null;
let authInstance: Auth | null = null;
let isInitialized = false;

/**
 * Firebase Auth インスタンスを（シングルトンとして）取得します。
 * クライアントサイドでのみ実行され、初期化は一度だけ行われます。
 * @returns {Auth | null} Authインスタンス、または設定不足の場合は null
 */
export const getAuthInstance = (): Auth | null => {
  // サーバーサイドでの実行を避けるための厳密なガード
  if (typeof window === "undefined") {
    return null;
  }

  // 既に初期化済みの場合は既存のインスタンスを返します
  if (isInitialized) {
    return authInstance;
  }

  // ★ 修正点: グローバル変数 '__firebase_config' に直接アクセスし、存在を確認
  // 環境が変数を注入することを前提とし、TypeScriptの警告を抑制するためanyを使用
  const globalConfig = (globalThis as any).__firebase_config as
    | string
    | undefined;

  if (!globalConfig) {
    // 設定が見つからない場合、初期化は行わずに null を返します。
    console.error(
      "CRITICAL: Firebase Configuration is missing. Global variable __firebase_config is undefined."
    );
    isInitialized = true; // 初期化処理自体は試みたとする
    return null;
  }

  try {
    const firebaseConfig = JSON.parse(globalConfig);

    // Firebaseアプリを初期化
    appInstance = initializeApp(firebaseConfig);

    // 認証サービスを取得
    authInstance = getAuth(appInstance);

    console.log("✅ Firebase Client initialized successfully.");
    isInitialized = true;

    return authInstance;
  } catch (error) {
    console.error("🔴 ERROR initializing Firebase:", error);
    isInitialized = true;
    return null;
  }
};
